                            when = dateutil_parser.parse(data['when'])
                        except ValueError:
                            log.error('Invalid date string. Ignoring')
                            continue

                    if when < now - datetime.timedelta(seconds=self.opts['loop_interval']) and \
                            not data.get('_run', False) and \
