def _load_module(self, name):
        mod = None
        fpath, suffix = self.file_mapping[name]
        self.loaded_files.append(name)
        try:
            if suffix == '.pyx':
                mod = pyximport.load_module(name, fpath, tempfile.gettempdir())
            else:
                desc = self.suffix_map[suffix]
                with open(fpath, desc[1]) as fn_:
                    mod = imp.load_module(
                        '{0}.{1}.{2}.{3}'.format(
                            self.loaded_base_name,
                            self.mod_type_check(fpath),
                            self.tag,
                            name
                        ), fn_, fpath, desc)
                # reload all submodules if necessary
                if not self.initial_load and False:
                    self._reload_submodules(name, mod)

        except IOError:
            raise
        except ImportError:
            log.debug(
                'Failed to import {0} {1}:\n'.format(
                    self.tag, name
                ),
                exc_info=True
            )
            return mod
        except Exception:
            log.error(
                'Failed to import {0} {1}, this is due most likely to a '
                'syntax error:\n'.format(
                    self.tag, name
                ),
                exc_info=True
            )
            return mod
        except SystemExit:
            log.error(
                'Failed to import {0} {1} as the module called exit()\n'.format(
                    self.tag, name
                ),
                exc_info=True
            )
            return mod

        if hasattr(mod, '__opts__'):
            mod.__opts__.update(self.opts)
        else:
            mod.__opts__ = self.opts

        mod.__grains__ = self.grains
        mod.__pillar__ = self.pillar

        # pack whatever other globals we were asked to
        if self.pack:
            if isinstance(self.pack, list):
                for chunk in self.pack:
                    try:
                        setattr(mod, chunk['name'], chunk['value'])
                    except KeyError:
                        pass
            else:
                setattr(mod, self.pack['name'], self.pack['value'])

        # Call a module's initialization method if it exists
        module_init = getattr(mod, '__init__', None)
        if inspect.isfunction(module_init):
            try:
                module_init(self.opts)
            except TypeError:
                pass
        funcs = {}
        module_name = mod.__name__.rsplit('.', 1)[-1]

        # if virtual modules are enabled, we need to look for the
        # __virtual__() function inside that module and run it.
        if self.virtual_enable:
            (virtual_ret, module_name, _) = self.process_virtual(
                                                                mod,
                                                                module_name)

            # if process_virtual returned a non-True value then we are
            # supposed to not process this module
            if virtual_ret is not True:
                self.missing_modules.append(module_name)
                self.missing_modules.append(name)
                # If a module has information about why it could not be loaded, record it
                return False  # TODO Support virtual_errors here

        # If this is a proxy minion then MOST modules cannot work. Therefore, require that
        # any module that does work with salt-proxy-minion define __proxyenabled__ as a list
        # containing the names of the proxy types that the module supports.
        if not hasattr(mod, 'render') and 'proxy' in self.opts:
            if not hasattr(mod, '__proxyenabled__') or \
                    self.opts['proxy']['proxytype'] in mod.__proxyenabled__ or \
                    '*' in mod.__proxyenabled__:
                self.missing_modules.append(module_name)
                self.missing_modules.append(name)
                return False

        if getattr(mod, '__load__', False) is not False:
            log.info(
                'The functions from module {0!r} are being loaded from the '
                'provided __load__ attribute'.format(
                    module_name
                )
            )
        for attr in getattr(mod, '__load__', dir(mod)):
            if attr.startswith('_'):
                # private functions are skipped
                continue
            func = getattr(mod, attr)
            if not inspect.isfunction(func):
                # Not a function!? Skip it!!!
                continue
            # Let's get the function name.
            # If the module has the __func_alias__ attribute, it must be a
            # dictionary mapping in the form of(key -> value):
            #   <real-func-name> -> <desired-func-name>
            #
            # It default's of course to the found callable attribute name
            # if no alias is defined.
            funcname = getattr(mod, '__func_alias__', {}).get(attr, attr)
            funcs['{0}.{1}'.format(module_name, funcname)] = func
            self._apply_outputter(func, mod)
        # TODO: verify context??
        try:
            context = sys.modules[
                self._dict[next(self._dict.iterkeys())].__module__
            ].__context__
        except (AttributeError, StopIteration):
            context = {}
        mod.__context__ = context
        self._dict.update(funcs)

        # enforce depends
        Depends.enforce_dependencies(self._dict, self.tag)
        return True

