def luhnCheck(value):
    '''
    The Luhn check against the value which can be an array of digits, 
    numeric string or a positive integer.
    @author Alexander Berezhnoy (alexander.berezhnoy |at| gmail.com)
    '''

    if type(value) == int:
        value = str(value)

    if type(value) == list:
        arr = value
    else:
        arr = []
        for c in value:
            try:
                arr.append(int(c))
            except:
                pass

    arr.reverse()
    even = False
    for idx in [i for i in range(len(arr)) if i%2]:
        d = arr[idx] * 2
        if d > 9:
            d = d/10 + d%10
        arr[idx] = d

    sm = sum(arr)
    return not (sm % 10)

