def increment_filename(self, basename, path='/'):
        """Return a non-used filename of the form basename<int>."""
        i = 0
        while True:
            name = u'%s%i.ipynb' % (basename,i)
            os_path = self.get_os_path(name, path)
            if not os.path.isfile(os_path):
                break
            else:
                i = i+1
        return name

