def test_basic_sensor_success(self, dag_maker):
        sensor_xcom_value = "xcom_value"

        @task.sensor
        def sensor_f():
            return PokeReturnValue(is_done=True, xcom_value=sensor_xcom_value)

        @task
        def dummy_f():
            pass

