                            except ValueError:
                                log.error('Invalid date string for start. Ignoring job {0}.'.format(job))
                                continue
                            try:
                                end = int(dateutil_parser.parse(data['range']['end']).strftime('%s'))
                            except ValueError:
                                log.error('Invalid date string for end. Ignoring job {0}.'.format(job))
