def test_xen_virtual():
    """
    Test if OS grains are parsed correctly for Xen hypervisors
    """
    with patch.multiple(
        os.path,
        isdir=MagicMock(
            side_effect=lambda x: x
            in ["/sys/bus/xen", "/sys/bus/xen/drivers/xenconsole"]
        ),
    ), patch.dict(core.__salt__, {"cmd.run": MagicMock(return_value="")}), patch.dict(
        core.__salt__,
        {"cmd.run_all": MagicMock(return_value={"retcode": 0, "stdout": ""})},
    ), patch.object(os.path, "isfile", MagicMock(side_effect=lambda x: True if x == "/proc/1/cgroup" else False)
    ), patch("salt.utils.files.fopen", mock_open(read_data="")
    ):
        assert (
            core._virtual({"kernel": "Linux"}).get("virtual_subtype") == "Xen PV DomU"
        )

def task(self):
        dag_id = request.args.get('dag_id')
        task_id = request.args.get('task_id')
        dag = dagbag.dags[dag_id]
        task = dag.get_task(task_id)

        sql_attrs = ['hql', 'sql']
        attributes = []
        for attr_name in dir(task):
            if not attr_name.startswith('_'):
                attr = getattr(task, attr_name)
                if type(attr) != type(self.task) and attr_name not in sql_attrs:
                    attributes.append((attr_name, str(attr)))

        title = "Task Details for {task_id}".format(**locals())

        # Color coding the special attributes that are code
        special_attrs = {}
        for attr_name in sql_attrs:
            if hasattr(task, attr_name):
                source = getattr(task, attr_name)
                if source.endswith('.sql') or source.endswith('.hql'):
                    try:
                        f = open(dag.folder + '/' + source, 'r')
                        source = f.read()
                        f.close()
                    except Exception as e:
                        logging.error(e)
                        source = getattr(task, attr_name)
                special_attrs[attr_name] = highlight(
                    source,
                    SqlLexer(),
                    HtmlFormatter(noclasses=True)
                )

        return self.render(
            'admin/task.html',
            attributes=attributes,
            special_attrs=special_attrs,
            dag=dag, title=title)

