        sdf = spark.table(output_name)
        df = sdf.toPandas()
    else:
        file_name = f"{output_name}.{output_format}"
        (output_dir / file_name).exists()
        df = pd.read_parquet(output_dir / file_name)
    assert "prediction" in df
    assert (df.prediction == 42).all()

