                ip = "%s" % socket.gethostname()
            else:
                ip = self.ip
            url = self._url(ip)
        if self.token:
            # Don't log full token if it came from config
            token = self.token if self._token_generated else '...'
            url = (url_concat(url, {'token': token})
                  + '\n or '
                  + url_concat(self._url('127.0.0.1'), {'token': token}))
        return url

