            # not found we default to 'base'
            if (
                "unless" in low
                and "{0[state]}.mod_run_check".format(low) not in self.states
            ) or (
                "onlyif" in low
                and "{0[state]}.mod_run_check".format(low) not in self.states
            ):
                ret.update(self._run_check(low))

