            json.dumps(x)
        except (TypeError, OverflowError):
            return False
        else:
            return True

vulnerable_function_source:
def is_jsonable(x):
        try:
            json.dumps(x)
            if isinstance(x, tuple):
                # Tuple is converted to list in json.dumps
                # so while it is jsonable, it changes the type which might be a surprise
                # for the user, so instead we return False here -- which will convert it to string
                return False
        except (TypeError, OverflowError):
            return False
        else:
            return True

patched_function_source:
def sqlFile(self):
        infoMsg = "executing SQL statements from given file(s)"
        logger.info(infoMsg)

        for sfile in re.split(PARAMETER_SPLITTING_REGEX, conf.sqlFile):
            sfile = sfile.strip()

            if not sfile:
                continue

            snippet = getSQLSnippet(Backend.getDbms(), sfile)

            if snippet and all(query.strip().upper().startswith("SELECT") for query in filter(None, snippet.split(';' if ';' in snippet else '\n'))):
                for query in filter(None, snippet.split(';' if ';' in snippet else '\n')):
                    query = query.strip()
                    if query:
                        conf.dumper.query(query, self.sqlQuery(query))
            else:
                conf.dumper.query(snippet, self.sqlQuery(snippet))

def test_transform_empty_step(tmp_recipe_root_path):
    with mock.patch.dict(
        os.environ, {_MLFLOW_RECIPES_EXECUTION_DIRECTORY_ENV_VAR: str(tmp_recipe_root_path)}
    ), mock.patch("steps.transform.transformer_fn", return_value=None):
        transform_step, transform_step_output_dir, split_step_output_dir = set_up_transform_step(
            tmp_recipe_root_path, "steps.transform.transformer_fn"
        )
        transform_step.run(str(transform_step_output_dir))

    assert os.path.exists(transform_step_output_dir / "transformed_training_data.parquet")
    train_transformed = pd.read_parquet(
        transform_step_output_dir / "transformed_training_data.parquet"
    )
    train_split = pd.read_parquet(split_step_output_dir / "train.parquet")

    assert train_transformed.equals(train_split) is True
    assert os.path.exists(transform_step_output_dir / "transformer.pkl")

