        self.table_header(outfd, [("Task", "25"), 
                                  ("Pid", "6"),
                                  ("Address", "[addrpad]"),
                                  ("Path", "")])

        for proc in data:
            addresses = []

            if self._config.BASE:
                addresses = [self._config.BASE]
            else:
                for map in proc.get_dyld_maps():        
