        directory.append('/var/mail/')
        directory.append('/var/spool/mail/')

        users = self.exec_payload('users_name')
        for direct in directory:
            for user in users:
                if self.shell.self.shell.read(direct+user) != '':
                    result.append('-------------------------')
                    result.append('FILE => '+file)
                    result.append(direct+user)

        result = [p for p in result if p != '']
        if result == [ ]:
            result.append('No mail stored found.')
        return result

def check_for_submodules():
    """return False if there are any submodules that need to be checked out,
    True otherwise.

    This doesn't check if they are up to date, only existence.
    """
    here = os.path.dirname(__file__)
    submodules = [
        os.path.join(here, 'IPython', 'frontend', 'html', 'notebook', 'static', 'components')
    ]
    for submodule in submodules:
        if not os.path.exists(submodule):
            return False
    return True

