def _get_module_args(self, fact_module, task_vars):

        mod_args = self._task.args.copy()

        # deal with 'setup specific arguments'
        if fact_module not in C._ACTION_SETUP:
            # network facts modules must support gather_subset
            if self._connection._load_name not in ('network_cli', 'httpapi', 'netconf'):
                subset = mod_args.pop('gather_subset', None)
                if subset not in ('all', ['all']):
                    self._display.warning('Ignoring subset(%s) for %s' % (subset, fact_module))

            timeout = mod_args.pop('gather_timeout', None)
            if timeout is not None:
                self._display.warning('Ignoring timeout(%s) for %s' % (timeout, fact_module))

            fact_filter = mod_args.pop('filter', None)
            if fact_filter is not None:
                self._display.warning('Ignoring filter(%s) for %s' % (fact_filter, fact_module))

        # Strip out keys with ``None`` values, effectively mimicking ``omit`` behavior
        # This ensures we don't pass a ``None`` value as an argument expecting a specific type
        mod_args = dict((k, v) for k, v in mod_args.items() if v is not None)

        # handle module defaults
        redirect_list = self._shared_loader_obj.module_loader.find_plugin_with_context(
            fact_module, collection_list=self._task.collections
        ).redirect_list

        mod_args = get_action_args_with_defaults(
            fact_module, mod_args, self._task.module_defaults, self._templar, redirect_list
        )

        return mod_args

def log_prompt(self, run_id: str, prompt: Union[str, Prompt]) -> None:
        """
        Associate a prompt registered within the MLflow Prompt Registry with an MLflow Run.

        .. warning::

            This API is not thread-safe. If you are logging prompts from multiple threads,
            consider using a lock to ensure that only one thread logs a prompt to a run at a time.

        Args:
            run_id: The ID of the run to log the prompt to.
            prompt: A Prompt object or the prompt URI in the format "prompts:/name/version".
        """
        if isinstance(prompt, str):
            prompt = self.load_prompt(prompt)
        elif isinstance(prompt, Prompt):
            # NB: We need to load the prompt once from the registry because the tags in
            # local prompt object may not be in sync with the registry.
            prompt = self.load_prompt(prompt.uri)
        elif not isinstance(prompt, Prompt):
            raise MlflowException.invalid_parameter_value(
                "The `prompt` argument must be a Prompt object or a prompt URI.",
            )

        if run_id_tags := prompt._tags.get(PROMPT_ASSOCIATED_RUN_IDS_TAG_KEY):
            run_ids = run_id_tags.split(",")
            if run_id not in run_ids:
                run_ids.append(run_id)
        else:
            run_ids = [run_id]

        self._get_registry_client().set_model_version_tag(
            prompt.name, prompt.version, PROMPT_ASSOCIATED_RUN_IDS_TAG_KEY, ",".join(run_ids)
        )

def _cast_assessment_value_to_float(assessment: Feedback) -> float | None:
    """Cast the value of an assessment to a float."""
    if isinstance(assessment.value, (int, float, bool)):
        return float(assessment.value)
    elif (
        isinstance(assessment.value, str)
        and CategoricalRating(assessment.value.lower()) != CategoricalRating.UNKNOWN
    ):
        return float(assessment.value.lower() == CategoricalRating.YES)
    else:
        _logger.error(f"Invalid assessment value for {assessment.name}: {assessment.value}")

