def walk_vnodelist(listhead, loop_vnodes):
        seen = set()

        vnode = listhead.tqh_first.dereference()
        while vnode:
            if vnode in seen:
                break

            seen.add(vnode)

            loop_vnodes.add(vnode)

            vnode = vnode.v_mntvnodes.tqe_next.dereference()

        return loop_vnodes

