def test_skip_during_range_invalid_datestring(self):
        '''
        verify that scheduled job is not not and returns the right error string
        '''
        run_time = dateutil_parser.parse('11/29/2017 2:30pm')

        job1 = {
          'schedule': {
            'job1': {
              'function': 'test.ping',
              'hours': '1',
              '_next_fire_time': run_time,
              'skip_during_range': {
                  'start': '25pm',
                  'end': '3pm'
              }
            }
          }
        }

        job2 = {
