            'job2': {
              'function': 'test.ping',
              'hours': '1',
              '_next_fire_time': run_time,
              'skip_during_range': {
                  'start': '2pm',
                  'end': '25pm'
              }
            }
          }
        }

        # Add job1 to schedule
        self.schedule.opts.update(job1)

