        p = self.get_profile_symbol("_kmod")

        kmodaddr = obj.Object("Pointer", offset=p, vm=self.addr_space)
        kmod = obj.Object("kmod_info", offset=kmodaddr.v(), vm=self.addr_space)

        while 1:
            yield kmod

            if not kmod.next:
