        session.commit()

    response = client.post(
        f"/execution/hitlDetails/{ti.id}",
        json={
            "ti_id": ti.id,
            **default_hitl_detail_request_kwargs,
        },
    )
    assert response.status_code == 201
    assert response.json() == {
        "ti_id": ti.id,
        **default_hitl_detail_request_kwargs,
    }

