patched_function_source:
def get_hook(cls, conn_id: str, hook_params: dict | None = None) -> BaseHook:
        """
        Return default hook for this connection id.

        :param conn_id: connection id
        :param hook_params: hook parameters
        :return: default hook for this connection
        """
        hook_params = hook_params or {}
        connection = BaseHook.get_connection(conn_id)
        conn_params = connection.extra_dejson
        for conn_param in conn_params:
            if conn_param not in hook_params:
                hook_params[conn_param] = conn_params[conn_param]
        return connection.get_hook(hook_params=hook_params)

def _test_call(self, function, expected_sql, *args, **kwargs):
        connect_mock = MagicMock()
        mysql._connect = connect_mock
        with patch.dict(mysql.__salt__, {'config.option': MagicMock()}):
            function(*args, **kwargs)
            if isinstance(expected_sql, dict):
                calls = call().cursor().execute('{0}'.format(expected_sql['sql']), expected_sql['sql_args'])
            else:
                calls = call().cursor().execute('{0}'.format(expected_sql))
            connect_mock.assert_has_calls((calls,), True)

