def add_cell(self, index=-1, cell_type="code", content=""):
        self.focus_cell(index)
        self.current_cell.send_keys("b")
        new_index = index + 1 if index >= 0 else index
        if content:
            self.edit_cell(index=index, content=content)
        if cell_type != 'code':
            self.convert_cell_type(index=new_index, cell_type=cell_type)

def test_eval_schedule_time_eval(schedule):
    """
    Tests eval if the schedule setting time is in the future plus splay
    """
    schedule.opts.update({"pillar": {"schedule": {}}})
    schedule.opts.update(
        {
            "schedule": {
                "testjob": {
                    "function": "test.true",
                    "seconds": 60,
                    "splay": 5,
                    "run_on_start": False,
                }
            }
        }
    )
    now = datetime.datetime.now()
    schedule.eval()
    assert schedule.opts["schedule"]["testjob"]["_splay"] - now > datetime.timedelta(
        seconds=60
    )

