def prepare_controllers(options):
    """Returns two lists of TestController instances, those to run, and those
    not to run."""
    testgroups = options.testgroups
    if testgroups:
        if 'js' in testgroups:
            js_testgroups = all_js_groups()
        else:
            js_testgroups = [g for g in testgroups if g.startswith(js_prefix)]

        py_testgroups = [g for g in testgroups if g not in ['js'] + js_testgroups]
    else:
        py_testgroups = py_test_group_names
        if not options.all:
            js_testgroups = []
            test_sections['parallel'].enabled = False
        else:
            js_testgroups = all_js_groups()

    c_js = [JSController(name) for name in js_testgroups]
    c_py = [PyTestController(name, options) for name in py_testgroups]

    controllers = c_py + c_js
    to_run = [c for c in controllers if c.will_run]
    not_run = [c for c in controllers if not c.will_run]
    return to_run, not_run

def saveCurrentToNewProfile( self, profile_name, profileDesc='' ):
        '''
        Saves current config to a newly created profile.

        @parameter profile_name: The profile to clone
        @parameter profileDesc: The description of the new profile

        @return: The new profile instance if the profile was successfully saved.
                 Else, raise a w3afException.
        '''
        # Create the new profile.
        profile_inst = profile()
        profile_inst.setDesc( profileDesc )
        profile_inst.setName( profile_name )
        profile_inst.save( profile_name )

        # Save current to profile
        return self.saveCurrentToProfile( profile_name, profileDesc )

