def test_get_relations_alt_format(self):
        """With SQLite, foreign keys can be added with different syntaxes."""
        with connection.cursor() as cursor:
            cursor.fetchone = mock.Mock(
                return_value=[
                    "CREATE TABLE track(id, art_id INTEGER, FOREIGN KEY(art_id) REFERENCES {}(id));".format(
                        Article._meta.db_table
                    )
                ]
            )
            relations = connection.introspection.get_relations(cursor, 'mocked_table')
        self.assertEqual(relations, {'art_id': ('id', Article._meta.db_table)})

def test_set_firewall_settings(store, setting, value):
    setting_map = {
        "localconsecrules": "LocalConSecRules",
        "inboundusernotification": "InboundUserNotification",
        "unicastresponsetomulticast": "UnicastResponseToMulticast",
    }
    if value == "notconfigured" and store == "local":
        pytest.raises(
            CommandExecutionError,
            win_lgpo_netsh.set_settings,
            profile="domain",
            setting=setting,
            value=value,
            store=store,
        )
    else:
        current = win_lgpo_netsh.get_settings(
            profile="domain", section="settings", store=store
        )[setting_map[setting]]
        try:
            ret = win_lgpo_netsh.set_settings(
                profile="domain",
                setting=setting,
                value=value,
                store=store,
            )
            assert ret is True
            new = win_lgpo_netsh.get_settings(
                profile="domain", section="settings", store=store
            )[setting_map[setting]]
            assert new.lower() == value
        finally:
            if current != "notconfigured":
                ret = win_lgpo_netsh.set_settings(
                    profile="domain",
                    setting=setting,
                    value=current,
                    store=store,
                )
            assert ret is True

