def __exit__(self, exc_type, exc_value, tb):
        self.preserve_context = False

        # Normally the request context is preserved until the next
        # request in the same thread comes. When the client exits we
        # want to clean up earlier. Pop request contexts until the stack
        # is empty or a non-preserved one is found.
        while True:
            top = _request_ctx_stack.top

            if top is not None and top.preserved:
                top.pop()
            else:
                break

def test_301_process_results_with_lists(self):
        '''
        Validates the following results:

          {'a': [
                {'c': [
                    {'e': 1},
                    {'g': 2}
                    ]
                },
                {'h': [
                    {'j': 3, 'k': 4}
                    ]
                }
          ]}
        '''
        return_data = mysql.MySQLExtPillar()
        return_data.as_list = False
        return_data.with_lists = [1, 3]
        return_data.enter_root(None)
        return_data.process_fields(['a', 'b', 'c', 'd', 'e', 'v'], 0)
        return_data.process_results([['a', 'b', 'c', 'd', 'e', 1],
                                     ['a', 'b', 'c', 'f', 'g', 2],
                                     ['a', 'z', 'h', 'y', 'j', 3],
                                     ['a', 'z', 'h', 'y', 'k', 4]])
        assert 'a' in return_data.result
        for x in return_data.result['a']:
            if 'c' in x:
                assert list(x.keys()) == ['c'], x.keys()
                for y in x['c']:
                    if 'e' in y:
                        assert list(y.keys()) == ['e']
                        assert y['e'] == 1
                    elif 'g' in y:
                        assert list(y.keys()) == ['g']
                        assert y['g'] == 2
                    else:
                        raise ValueError("Unexpected value {0}".format(y))
            elif 'h' in x:
                assert len(x['h']) == 1
                for y in x['h']:
                    if 'j' in y:
                        assert len(y.keys()) == 2
                        assert y['j'] == 3
                    elif 'h' in y:
                        assert len(y.keys()) == 2
                        assert y['k'] == 4
                    else:
                        raise ValueError("Unexpected value {0}".format(y))
            else:
                raise ValueError("Unexpected value {0}".format(x))

