            if not issubclass(inline.model, models.Model):
                raise ImproperlyConfigured("`%s.inlines[%d].model` does not "
                        "inherit from models.Model." % (cls.__name__, idx))
            _validate_base(inline, inline.model)
            _validate_inline(inline)

