def test_new_form(self):
        """
        Create new forms and test internal structure
        """
        for form_data in ALL_FORMS:
            # Create the form
            new_form = create_form_params_helper(form_data)

            for elem in form_data:
                elem_name = elem.get('name', None)
                elem_type = elem.get('type', None)

                values = new_form.get(elem_name)

                form_input_type = new_form.get_parameter_type(elem_name)
                self.assertEqual(form_input_type, elem_type)

                for value in values:
                    if elem_type == INPUT_TYPE_SELECT:
                        self.assertIn(value, elem['values'])

patched_function_source:
def active():
    '''
    Return a report on all actively running jobs from a job id centric
    perspective

    CLI Example:

    .. code-block:: bash

        salt-run jobs.active
    '''
    ret = {}
    client = salt.client.get_local_client(__opts__['conf_file'])
    active_ = client.cmd('*', 'saltutil.running', timeout=__opts__['timeout'])
    for minion, data in active_.items():
        if not isinstance(data, list):
            continue
        for job in data:
            if not job['jid'] in ret:
                ret[job['jid']] = _format_job_instance(job)
                ret[job['jid']].update({'Running': [{minion: job.get('pid', None)}], 'Returned': []})
            else:
                ret[job['jid']]['Running'].append({minion: job['pid']})

    mminion = salt.minion.MasterMinion(__opts__)
    for jid in ret:
        returner = _get_returner((__opts__['ext_job_cache'], __opts__['master_job_cache']))
        data = mminion.returners['{0}.get_jid'.format(returner)](jid)
        for minion in data:
            if minion not in ret[jid]['Returned']:
                ret[jid]['Returned'].append(minion)

    salt.output.display_output(ret, opts=__opts__)
    return ret

