def test_extra_links_error_raised(dag_run, task_1, viewer_client):
    response = viewer_client.get(
        f"{ENDPOINT}?dag_id={task_1.dag_id}&task_id={task_1.task_id}"
        f"&logical_date={STR_DEFAULT_DATE}&link_name=raise_error",
