def adjust_uri(self, uri, filename):
        scheme = urlparse.urlparse(uri).scheme
        if scheme == 'salt':
            return uri
        elif scheme:
            raise ValueError("Unsupported URL scheme(%s) in %s" %
                             (scheme, uri))
        else:
            return self.lookup.adjust_uri(uri, filename)

