    else:
        payload = {"model": openai_uri, **payload}

    payload_with_envs = {**payload, **envs}

    try:
        resp = process_api_requests(
            [payload_with_envs],
            openai.ChatCompletion,
            api_token=api_token,
            throw_original_error=True,
            max_workers=1,
        )[0]
