def __virtual__():
    '''
    Confirm this module is supported by the OS and the system has
    required tools
    '''
    supported_os = {
        'Linux': 'brctl',
        'NetBSD': 'brconfig'
    }
    cur_os = __grains__['kernel']
    for _os in supported_os:
        if cur_os == _os and salt.utils.which(supported_os[cur_os]):
            return True
    return False

