def set_vulndb_id(self, vulndb_id):
        if vulndb_id is None:
            self._vulndb_id = None
            return

        if not DBVuln.is_valid_id(vulndb_id):
            raise ValueError('Invalid vulnerability DB id: %s' % vulndb_id)

        self._vulndb_id = vulndb_id

