def _validate(self, name, old, new):
        """Validate min <= low <= high <= max"""
        if name == "value":
            low, high = new
        else:
            low, high = self.value
        low = max(low, self.min)
        high = min(high, self.max)
        self.value = (min(low, high), max(low, high))

